package com.agacostays.payroll.mapper; import com.agacostays.payroll.entity.SalarySlip; import com.agacostays.payroll.dto.response.SalarySlipResponse; import org.springframework.stereotype.Component; @Component public class SalarySlipMapper{public SalarySlipResponse toResponse(SalarySlip x){return new SalarySlipResponse(x.getSalarySlipId(),x.getPayrollId(),x.getStaffId(),x.getMonth(),x.getYear(),x.getSalarySlipUrl(),x.getSentEmailStatus().name(),x.getGeneratedAt());}}